class Rettangolo:
    def __init__(self, b, h):
        self.b = b
        self.h = h

    def area(self):
        return self.b * self.h

    def inerzia(self):
        return self.b * self.h**3 / 12

r = Rettangolo(100, 200)
print(r.area(), r.inerzia())
